<?php
namespace App\Controllers;
use App\Services\{SmsService,MedianaSmsService,LogSmsService};use App\Support\Jwt;use Throwable;
final class AuthController{private SmsService$sms;public function __construct(){$this->sms=env('SMS_DRIVER','log')==='mediana'?new MedianaSmsService:new LogSmsService;}
public function requestOtp():never{$d=body();$m=self::mobile($d['mobile']??'');if(!$m)jsonResponse(['message'=>'شماره موبایل معتبر نیست.'],422);$q=db()->prepare("SELECT COUNT(*) FROM otp_codes WHERE mobile=? AND created_at>DATE_SUB(NOW(),INTERVAL 1 HOUR)");$q->execute([$m]);if((int)$q->fetchColumn()>=(int)env('OTP_MAX_SENDS_PER_HOUR',5))jsonResponse(['message'=>'تعداد درخواست بیش از حد مجاز است.'],429);$q=db()->prepare("SELECT created_at FROM otp_codes WHERE mobile=? ORDER BY id DESC LIMIT 1");$q->execute([$m]);$last=$q->fetchColumn();if($last&&time()-strtotime($last)<(int)env('OTP_COOLDOWN_SECONDS',60))jsonResponse(['message'=>'برای ارسال مجدد کمی صبر کنید.'],429);$code=(string)random_int(10000,99999);$ttl=(int)env('OTP_TTL_SECONDS',120);$q=db()->prepare("INSERT INTO otp_codes(mobile,code_hash,expires_at)VALUES(?,?,DATE_ADD(NOW(),INTERVAL ? SECOND))");$q->execute([$m,password_hash($code,PASSWORD_DEFAULT),$ttl]);$id=(int)db()->lastInsertId();try{$r=$this->sms->sendOtp($m,$code);db()->prepare("UPDATE otp_codes SET provider_message_id=? WHERE id=?")->execute([$r['message_id'],$id]);$this->log($m,'sent',$r);jsonResponse(['message'=>'کد تأیید ارسال شد.','expires_in'=>$ttl,'resend_after'=>(int)env('OTP_COOLDOWN_SECONDS',60)]);}catch(Throwable$e){db()->prepare("UPDATE otp_codes SET status='failed' WHERE id=?")->execute([$id]);$this->log($m,'failed',[],$e->getMessage());jsonResponse(['message'=>'ارسال پیامک ناموفق بود.'],503);}}
public function verifyOtp():never{$d=body();$m=self::mobile($d['mobile']??'');$code=(string)($d['code']??'');$q=db()->prepare("SELECT * FROM otp_codes WHERE mobile=? AND purpose='login' ORDER BY id DESC LIMIT 1");$q->execute([$m]);$o=$q->fetch();if(!$o||$o['status']!=='sent')jsonResponse(['message'=>'کد فعال وجود ندارد.'],422);if(strtotime($o['expires_at'])<time()){db()->prepare("UPDATE otp_codes SET status='expired' WHERE id=?")->execute([$o['id']]);jsonResponse(['message'=>'کد منقضی شده است.'],422);}if((int)$o['attempts']>=(int)env('OTP_MAX_ATTEMPTS',5))jsonResponse(['message'=>'تعداد تلاش مجاز تمام شده است.'],429);if(!password_verify($code,$o['code_hash'])){db()->prepare("UPDATE otp_codes SET attempts=attempts+1 WHERE id=?")->execute([$o['id']]);jsonResponse(['message'=>'کد صحیح نیست.'],422);}db()->beginTransaction();db()->prepare("UPDATE otp_codes SET status='verified',verified_at=NOW() WHERE id=?")->execute([$o['id']]);db()->prepare("INSERT INTO users(mobile,mobile_verified_at)VALUES(?,NOW()) ON DUPLICATE KEY UPDATE mobile_verified_at=NOW()")->execute([$m]);$q=db()->prepare("SELECT * FROM users WHERE mobile=?");$q->execute([$m]);$u=$q->fetch();$s=db()->prepare("SELECT COUNT(*) FROM subscriptions WHERE user_id=?");$s->execute([$u['id']]);$u['has_subscription']=(int)$s->fetchColumn()>0;db()->commit();jsonResponse(['access_token'=>Jwt::issue((int)$u['id']),'token_type'=>'Bearer','expires_in'=>3600,'user'=>$u]);}
private function log(string$m,string$s,array$r,string$e=null):void{db()->prepare("INSERT INTO sms_logs(mobile,provider,template_code,provider_message_id,status,request_payload,response_payload,error_message)VALUES(?,?,?,?,?,?,?,?)")->execute([$m,env('SMS_DRIVER','log'),env('MEDIANA_PATTERN_CODE'),$r['message_id']??null,$s,json_encode($r['request']??[]),json_encode($r['response']??[]),$e]);}private static function mobile(string$m):?string{$m=preg_replace('/\D/','',$m);if(str_starts_with($m,'98'))$m='0'.substr($m,2);return preg_match('/^09\d{9}$/',$m)?$m:null;}}
